import java.util.*;

class Solution {
  public int maximumBeauty(int[] flowers) {
    int n = flowers.length;
    long[] positive = new long[n + 1]; // prefix sums of positive beauties only
    for (int i = 0; i < n; i++) positive[i + 1] = positive[i] + Math.max(0, flowers[i]);
    Map<Integer, Integer> first = new HashMap<>();
    long best = Long.MIN_VALUE;
    // keep both ends, plus every positive flower between them
    for (int j = 0; j < n; j++) {
      Integer i = first.get(flowers[j]);
      if (i == null) first.put(flowers[j], j);
      else best = Math.max(best, 2L * flowers[j] + positive[j] - positive[i + 1]);
    }
    return (int) best;
  }
}
